Find the length of the interval $AB$.
[tikz]
\begin{tikzpicture}[scale=0.55]
\draw[step=1,gray!25,very thin] (-5,-5) grid (5,5);
\draw[<->] (-5.5,0)--(5.5,0) node[right]{$x$};
\draw[<->] (0,-5.5)--(0,5.5) node[above]{$y$};
\foreach \i in {-5,-4,-3,-2,-1,1,2,3,4,5} \node[below,font=\scriptsize] at (\i,0){$\i$};
\foreach \i in {-5,-4,-3,-2,-1,1,2,3,4,5} \node[left,font=\scriptsize] at (0,\i){$\i$};
\draw[thick,blue] (-2,-2)--(1,2);
\fill (-2,-2) circle (2.5pt);
\node[below left,font=\footnotesize] at (-2,-2){$A$};
\fill (1,2) circle (2.5pt);
\node[above right,font=\footnotesize] at (1,2){$B$};
\end{tikzpicture}
[/tikz]

